package com.example.onlineshop.catalog.domain;
import static org.assertj.core.api.Assertions.*;
import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class CatalogProductTest {
 private static final Instant NOW=Instant.parse("2026-10-24T00:00:00Z");
 @Test void enforcesDefaultSkuVariantAndLifecycleRules(){var product=product();var size=attribute(AttributeScope.SKU,true);var small=size.addValue(UUID.randomUUID(),"small","Small");var first=sku("tea-small",true);first.assign(size,small);product.addSku(first);assertThat(product.defaultSku()).isSameAs(first);var duplicate=sku("tea-small-2",false);duplicate.assign(size,small);assertThatThrownBy(()->product.addSku(duplicate)).isInstanceOf(ProductValidationException.class).hasMessageContaining("variant");product.archive(UUID.randomUUID(),NOW.plusSeconds(1),0);assertThatThrownBy(()->product.addSku(sku("late",false))).isInstanceOf(ProductValidationException.class).hasMessageContaining("archived");}
 @Test void validatesScopeTypedValuesAndImmutableIdentityAfterUse(){var productOnly=attribute(AttributeScope.PRODUCT,false);var value=productOnly.addValue(UUID.randomUUID(),"green",null);assertThatThrownBy(()->sku("tea",true).assign(productOnly,value)).isInstanceOf(ProductValidationException.class);assertThatThrownBy(()->productOnly.addValue(UUID.randomUUID(),42L,null)).isInstanceOf(ProductValidationException.class);assertThatThrownBy(()->productOnly.changeIdentity("shade",AttributeDataType.INTEGER)).isInstanceOf(ProductValidationException.class).hasMessageContaining("immutable");}
 @Test void validatesMoneyStockAndOptimisticVersions(){assertThatThrownBy(()->new ProductSku(UUID.randomUUID(),"tea",LifecycleStatus.ACTIVE,new BigDecimal("-1"),"NZD",1,true,0)).isInstanceOf(ProductValidationException.class);var sku=sku("tea",true);sku.changeStock(2,0);assertThat(sku.version()).isEqualTo(1);assertThatThrownBy(()->sku.changeStock(3,0)).isInstanceOf(OptimisticConflictException.class);assertThatThrownBy(()->sku.changeStock(-1,1)).isInstanceOf(ProductValidationException.class);}
 @Test void reassignmentRevalidatesAxisSignatureAndIgnoresDescriptiveAttributes(){var p=product();var axis=attribute(AttributeScope.SKU,true);var red=axis.addValue(UUID.randomUUID(),"red","Red");var blue=axis.addValue(UUID.randomUUID(),"blue","Blue");var note=attribute(AttributeScope.SKU,false);var noteValue=note.addValue(UUID.randomUUID(),"note","Note");var a=sku("a",true);a.assign(axis,red);var b=sku("b",false);b.assign(axis,blue);p.addSku(a);p.addSku(b);p.assignSku(a.id(),note,noteValue);assertThat(a.variantSignature()).doesNotContain(note.id().toString());assertThatThrownBy(()->p.assignSku(b.id(),axis,red)).isInstanceOf(ProductValidationException.class).hasMessageContaining("variant");}
 @Test void twoAxisVariantSignatureIsDeterministicAndLossless(){var colour=attribute(AttributeScope.SKU,true);var red=colour.addValue(UUID.randomUUID(),"red","Red");var size=attribute(AttributeScope.SKU,true);var large=size.addValue(UUID.randomUUID(),"large","Large");var first=sku("first",true);first.assign(colour,red);first.assign(size,large);var second=sku("second",true);second.assign(size,large);second.assign(colour,red);assertThat(first.variantSignature()).hasSize(147).isEqualTo(second.variantSignature()).contains(colour.id().toString(),red.id().toString(),size.id().toString(),large.id().toString());}
 @Test void archivedAttributesAreRejectedAndArchiveCascades(){var p=product();var a=attribute(AttributeScope.SKU,true);var value=a.addValue(UUID.randomUUID(),"red",null);a.archive();assertThatThrownBy(()->sku("x",true).assign(a,value)).isInstanceOf(ProductValidationException.class).hasMessageContaining("not active");var sku=sku("default",true);p.addSku(sku);p.activate(null,NOW.plusSeconds(1),0);p.archive(null,NOW.plusSeconds(2),1);assertThat(p.status()).isEqualTo(LifecycleStatus.ARCHIVED);assertThat(sku.status()).isEqualTo(LifecycleStatus.ARCHIVED);assertThatThrownBy(()->p.activate(null,NOW.plusSeconds(3),2)).isInstanceOf(ProductValidationException.class);}
 @Test void preservesFrozenV1NameRepresentation(){var p=new CatalogProduct(UUID.randomUUID(),null,"tea","  Padded Tea  ","Leaves",LifecycleStatus.ACTIVE,null,null,NOW,NOW,0);assertThat(p.name()).isEqualTo("  Padded Tea  ");}
 private static CatalogProduct product(){return new CatalogProduct(UUID.randomUUID(),null,"tea","Tea","Leaves",LifecycleStatus.DRAFT,null,null,NOW,NOW,0);}
 private static ProductAttribute attribute(AttributeScope scope,boolean axis){return new ProductAttribute(UUID.randomUUID(),"colour","Colour",AttributeDataType.TEXT,scope,axis,LifecycleStatus.ACTIVE);}
 private static ProductSku sku(String code,boolean defaultSku){return new ProductSku(UUID.randomUUID(),code,LifecycleStatus.ACTIVE,new BigDecimal("12.30"),"NZD",4,defaultSku,0);}
}
